	# Índice del checkbox actual (ej. "Checkbox_0" -> 0)
	try:
		index = int(self.name.split("_")[-1])
	except:
		index = 0

	parent = self.parent
	isChecked = self.props.selected

	# Cantidad esperada según tu array custom
	total = len(parent.custom.checkboxAnswers)

	# 1) Apagar TODOS (custom y visual)
	for i in range(total):
		parent.custom.checkboxAnswers[i] = False
		compName = "Checkbox_{}".format(i)
		try:
			parent.getChild(compName).props.selected = False
		except:
			pass  # si no existe, continuar

	# 2) Encender SOLO el actual si quedó marcado
	if isChecked:
		parent.custom.checkboxAnswers[index] = True
		compName = "Checkbox_{}".format(index)
		try:
			parent.getChild(compName).props.selected = True
		except:
			pass
		parent.custom.item.answer = index
	else:
		parent.custom.item.answer = None

